import * as THREE from 'three'
import { MAX_AMP, waveShaderChunk, waveUniforms } from './waves.js'

const vertexHead = /* glsl */ `
uniform float uTime;
varying vec3 vWorld;
varying vec3 vNormalW;
varying float vCrest;
varying vec2 vXZ;
`

const fragmentHead = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDir;
uniform vec3 uCam;
uniform vec3 uPlayer;
uniform float uDawn;
uniform float uSpeed;
varying vec3 vWorld;
varying vec3 vNormalW;
varying float vCrest;
varying vec2 vXZ;

float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * vnoise(p);
    p = p * 2.04 + vec2(17.0, 9.0);
    a *= 0.5;
  }
  return v;
}
vec3 skyTint(vec3 r) {
  float h = max(r.y, 0.0);
  vec3 horizon = mix(vec3(0.50, 0.22, 0.23), vec3(1.18, 0.55, 0.30), uDawn);
  vec3 zenith = mix(vec3(0.018, 0.035, 0.085), vec3(0.06, 0.12, 0.25), uDawn);
  vec3 c = mix(horizon, zenith, smoothstep(0.0, 0.55, h));
  float sd = max(dot(r, uSunDir), 0.0);
  c += vec3(1.0, 0.46, 0.18) * (pow(sd, 7.0) * 0.30 + pow(sd, 90.0) * 1.1 + pow(sd, 900.0) * 3.0);
  return c;
}
`

const fragmentMain = /* glsl */ `
void main() {
  vec3 V = normalize(uCam - vWorld);
  vec3 N = normalize(vNormalW);

  // Fine wind ripples: two cheap gradient streams to break up the big swell.
  vec2 rp = vWorld.xz;
  float t = uTime;
  float r1 = sin(rp.x * 1.7 + t * 1.15 + sin(rp.y * 1.2 - t * 0.7));
  float r2 = sin(rp.y * 1.45 - t * 0.95 + sin(rp.x * 0.9 + t * 0.5));
  float r3 = sin((rp.x + rp.y) * 2.9 + t * 1.6);
  N.x += (r1 * 0.035 + r3 * 0.018);
  N.z += (r2 * 0.035 + r3 * 0.018);
  N = normalize(N);

  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 4.0);
  fres = 0.045 + 0.955 * fres;

  vec3 R = reflect(-V, N);
  vec3 sky = skyTint(R);

  vec3 deep = mix(vec3(0.006, 0.030, 0.050), vec3(0.012, 0.070, 0.098), uDawn);
  vec3 shallow = mix(vec3(0.012, 0.20, 0.22), vec3(0.09, 0.44, 0.37), uDawn);
  float crestT = smoothstep(-1.5, 6.0, vCrest);
  vec3 body = mix(deep, shallow, crestT * 0.62 + fres * 0.20);

  vec3 col = mix(body, sky, fres * 0.78);

  // Sun glitter path + crisp sparkles on the faces.
  vec3 sunCol = vec3(1.0, 0.62, 0.30);
  float sd = max(dot(R, uSunDir), 0.0);
  float sparkle = vnoise(rp * 4.6 + vec2(t * 0.9, -t * 0.6));
  sparkle *= vnoise(rp * 11.0 - vec2(t * 1.4, t * 0.8));
  float glint = pow(sd, 700.0) * (2.0 + 16.0 * sparkle);
  float sheen = pow(sd, 60.0) * 0.32;
  col += sunCol * (glint + sheen) * (0.65 + 0.5 * uDawn);

  // Light bleeding through the crests when looking into the sunrise.
  float back = pow(max(dot(-V, uSunDir), 0.0), 2.5);
  col += shallow * back * crestT * 0.55;
  col += vec3(1.0, 0.62, 0.3) * back * crestT * crestT * 0.16;

  // Foam on the crests.
  float cn = smoothstep(0.30, 0.88, vCrest / (${MAX_AMP.toFixed(4)} * 0.72));
  float steep = 1.0 - clamp(N.y, 0.0, 1.0);
  float wc = smoothstep(0.055, 0.20, steep);
  float fn = fbm(rp * 0.55 + vec2(t * 0.045, t * 0.02));
  float fn2 = fbm(rp * 2.3 - vec2(t * 0.16, t * 0.11));
  float foam = smoothstep(0.34, 0.74, cn * 0.92 + fn * 0.32 + wc * 0.34);
  foam *= smoothstep(0.20, 0.62, fn + fn2 * 0.4 + wc * 0.22);
  foam = clamp(foam, 0.0, 1.0);

  // Board wake ring.
  float wd = distance(vWorld.xz, uPlayer.xz);
  float ring = smoothstep(4.6, 0.4, wd) * smoothstep(0.25, 0.9, fn2 + 0.35);
  ring *= 0.55 + 0.45 * smoothstep(0.0, 8.0, uSpeed);
  foam = clamp(foam + ring * 0.85, 0.0, 1.0);

  vec3 foamCol = mix(vec3(0.55, 0.58, 0.68), vec3(1.08, 0.94, 0.80), uDawn);
  foamCol *= 0.78 + 0.35 * max(dot(N, uSunDir), 0.0);
  col = mix(col, foamCol, foam * 0.9);

  // Atmospheric haze towards the horizon.
  float dist = distance(uCam, vWorld);
  vec3 haze = mix(vec3(0.44, 0.22, 0.24), vec3(1.06, 0.52, 0.29), uDawn);
  haze = mix(haze, skyTint(normalize(vec3(V.x, 0.02, V.z))), 0.45);
  col = mix(col, haze, smoothstep(230.0, 760.0, dist));

  gl_FragColor = vec4(col, 1.0);
}
`

export function createOcean() {
  const uniforms = {
    uTime: { value: 0 },
    uSunDir: { value: new THREE.Vector3(0, 0.05, -1).normalize() },
    uCam: { value: new THREE.Vector3() },
    uPlayer: { value: new THREE.Vector3() },
    uDawn: { value: 0.15 },
    uSpeed: { value: 0 },
  }
  const waves = waveUniforms()
  waves.forEach((w, i) => {
    uniforms[`w${i}Dir`] = { value: new THREE.Vector2(w.uDir.value[0], w.uDir.value[1]) }
    uniforms[`w${i}K`] = { value: w.uK.value }
    uniforms[`w${i}Amp`] = { value: w.uAmp.value }
    uniforms[`w${i}Omega`] = { value: w.uOmega.value }
    uniforms[`w${i}Phase`] = { value: w.uPhase.value }
    uniforms[`w${i}Chop`] = { value: w.uChop.value }
  })

  const decl = []
  for (let i = 0; i < waves.length; i++) {
    decl.push(`uniform vec2 w${i}Dir; uniform float w${i}K; uniform float w${i}Amp; uniform float w${i}Omega; uniform float w${i}Phase; uniform float w${i}Chop;`)
  }

  const chunk = waveShaderChunk('w')

  const vertexShader = vertexHead + decl.join('\n') + /* glsl */ `
void main() {
  vec3 p = (modelMatrix * vec4(position, 1.0)).xyz;
  vec3 disp = vec3(0.0);
  float crest = 0.0;
  vec3 tangentX = vec3(1.0, 0.0, 0.0);
  vec3 tangentZ = vec3(0.0, 0.0, 1.0);
${chunk.body}
  p += disp;
  vWorld = p;
  vXZ = p.xz;
  vCrest = crest;
  vNormalW = normalize(cross(tangentZ, tangentX));
  gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
}
`

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader,
    fragmentShader: fragmentHead + fragmentMain,
    side: THREE.DoubleSide,
  })

  const geometry = new THREE.PlaneGeometry(1150, 1150, 340, 340)
  geometry.rotateX(-Math.PI / 2)
  const mesh = new THREE.Mesh(geometry, material)
  mesh.frustumCulled = false
  mesh.renderOrder = -1

  const snap = 1150 / 340
  return {
    mesh,
    uniforms,
    update(playerPos, time, dawn, speed) {
      uniforms.uTime.value = time
      uniforms.uPlayer.value.copy(playerPos)
      uniforms.uDawn.value = dawn
      uniforms.uSpeed.value = speed
      mesh.position.x = Math.round(playerPos.x / snap) * snap
      mesh.position.z = Math.round(playerPos.z / snap) * snap
    },
  }
}

import * as THREE from 'three'

function glowTexture(inner = 'rgba(255,236,190,1)', outer = 'rgba(255,140,60,0)') {
  const c = document.createElement('canvas')
  c.width = c.height = 256
  const g = c.getContext('2d')
  const grad = g.createRadialGradient(128, 128, 0, 128, 128, 128)
  grad.addColorStop(0, inner)
  grad.addColorStop(0.18, 'rgba(255,214,150,0.85)')
  grad.addColorStop(0.42, 'rgba(255,150,80,0.28)')
  grad.addColorStop(1, outer)
  g.fillStyle = grad
  g.fillRect(0, 0, 256, 256)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

const skyVert = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`

const skyFrag = /* glsl */ `
uniform vec3 uSunDir;
uniform float uDawn;
uniform float uTime;
uniform float uFlash;
varying vec3 vDir;

float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p);
    p = p * 2.02 + vec2(11.0, 7.0);
    a *= 0.5;
  }
  return v;
}

void main() {
  vec3 d = normalize(vDir);
  float h = max(d.y, 0.0);
  float sd = max(dot(d, uSunDir), 0.0);

  vec3 zenith = mix(vec3(0.016, 0.028, 0.075), vec3(0.052, 0.115, 0.255), uDawn);
  vec3 mid = mix(vec3(0.115, 0.070, 0.165), vec3(0.30, 0.19, 0.34), uDawn);
  vec3 horizon = mix(vec3(0.52, 0.21, 0.21), vec3(1.30, 0.56, 0.26), uDawn);

  vec3 col = mix(horizon, mid, smoothstep(0.0, 0.26, h));
  col = mix(col, zenith, smoothstep(0.18, 0.82, h));

  // Broad dawn halo + three-stage sun bloom.
  col += vec3(1.0, 0.45, 0.17) * (pow(sd, 5.0) * 0.20 + pow(sd, 36.0) * 0.55 + pow(sd, 320.0) * 1.0) * mix(0.75, 1.25, uDawn);
  col += vec3(0.85, 0.32, 0.12) * pow(sd, 2.5) * exp(-h * 6.5) * 0.45;

  // Clouds: a warm streaked deck near the horizon, thin cold wisps above.
  vec2 cuv = d.xz / (h + 0.115) * 0.58;
  float band = smoothstep(0.012, 0.075, h) * (1.0 - smoothstep(0.12, 0.55, h));
  float c1 = fbm(cuv * vec2(1.05, 1.65) + vec2(uTime * 0.0045, 0.0));
  float c2 = fbm(cuv * vec2(2.4, 3.8) - vec2(uTime * 0.007, 1.7));
  float cloud = smoothstep(0.49, 0.74, c1 * 0.8 + c2 * 0.32) * band;
  cloud *= smoothstep(-0.02, 0.06, d.y);
  vec3 cloudShadow = mix(vec3(0.10, 0.07, 0.14), vec3(0.34, 0.17, 0.27), uDawn);
  vec3 cloudLit = mix(vec3(0.62, 0.30, 0.26), vec3(1.75, 0.78, 0.42), uDawn) * (0.35 + 0.95 * pow(sd, 1.6));
  col = mix(col, mix(cloudShadow, cloudLit, smoothstep(0.12, 0.85, c1)), cloud * 0.9);

  float wisp = smoothstep(0.56, 0.86, fbm(cuv * vec2(0.65, 3.2) + vec2(uTime * 0.002, 4.0)));
  wisp *= smoothstep(0.22, 0.55, h) * (1.0 - smoothstep(0.6, 0.95, h));
  col = mix(col, cloudLit * 0.75, wisp * 0.35);

  // The disc itself: hotter and larger as the dawn completes.
  float disc = smoothstep(0.99956, 0.99986, sd);
  col += vec3(3.4, 2.05, 1.05) * disc * (0.9 + 1.7 * uDawn);
  col += vec3(6.0, 4.2, 2.4) * smoothstep(0.99988, 0.99997, sd) * uDawn;

  // Below the horizon: deep haze for reflections / glancing views.
  if (d.y < 0.0) {
    col = mix(col, horizon * 0.72, smoothstep(0.0, -0.10, d.y));
  }

  col += vec3(1.0, 0.55, 0.28) * uFlash * (0.25 + pow(sd, 4.0));

  gl_FragColor = vec4(col, 1.0);
}
`

function ridgeGeometry(width, height, seed) {
  const shape = new THREE.Shape()
  shape.moveTo(-width / 2, 0)
  const points = 18
  for (let i = 0; i <= points; i++) {
    const x = -width / 2 + (i / points) * width
    const roll = Math.sin(i * 12.9898 + seed) * 43758.5453
    const rnd = roll - Math.floor(roll)
    const peak = Math.sin((i / points) * Math.PI) ** 0.7
    const y = (0.18 + rnd * 0.72) * height * peak
    shape.lineTo(x, y)
  }
  shape.lineTo(width / 2, 0)
  shape.closePath()
  return new THREE.ShapeGeometry(shape)
}

function makeBird() {
  const geo = new THREE.BufferGeometry()
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3))
  const mat = new THREE.LineBasicMaterial({ color: 0x1c1420, transparent: true, opacity: 0.85, fog: false })
  const line = new THREE.Line(geo, mat)
  line.frustumCulled = false
  return line
}

export function createBackdrop(scene) {
  const group = new THREE.Group()
  scene.add(group)

  const skyUniforms = {
    uSunDir: { value: new THREE.Vector3(0.26, 0.08, -0.96).normalize() },
    uDawn: { value: 0.15 },
    uTime: { value: 0 },
    uFlash: { value: 0 },
  }
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(1800, 48, 32),
    new THREE.ShaderMaterial({
      uniforms: skyUniforms,
      vertexShader: skyVert,
      fragmentShader: skyFrag,
      side: THREE.BackSide,
      depthWrite: false,
      depthTest: false,
    }),
  )
  sky.frustumCulled = false
  sky.renderOrder = -10
  group.add(sky)

  const sunGlow = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: glowTexture(),
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: false,
      opacity: 0.85,
      fog: false,
    }),
  )
  sunGlow.scale.setScalar(560)
  sunGlow.renderOrder = -9
  group.add(sunGlow)

  const islandMat = new THREE.MeshBasicMaterial({ color: 0x181320, fog: false })
  const island = new THREE.Mesh(ridgeGeometry(620, 92, 3.1), islandMat)
  island.position.set(-300, -4, -720)
  group.add(island)
  const island2 = new THREE.Mesh(ridgeGeometry(300, 42, 8.7), islandMat)
  island2.position.set(-40, -3, -860)
  group.add(island2)
  const island3 = new THREE.Mesh(ridgeGeometry(210, 26, 5.3), islandMat)
  island3.position.set(420, -3, -830)
  group.add(island3)

  const birds = []
  const birdMat = new THREE.LineBasicMaterial({ color: 0x221724, transparent: true, opacity: 0.8, fog: false })
  for (let i = 0; i < 9; i++) {
    const bird = makeBird()
    bird.material = birdMat
    bird.userData = {
      angle: Math.random() * Math.PI * 2,
      radius: 55 + Math.random() * 120,
      height: 16 + Math.random() * 42,
      phase: Math.random() * Math.PI * 2,
      speed: 0.09 + Math.random() * 0.08,
      size: 1.1 + Math.random() * 0.9,
    }
    birds.push(bird)
    group.add(bird)
  }

  const sunDir = new THREE.Vector3()
  const tmp = new THREE.Vector3()

  return {
    group,
    sunDir,
    skyUniforms,
    update(camera, time, dawn, flash, focus) {
      skyUniforms.uTime.value = time
      skyUniforms.uDawn.value = dawn
      skyUniforms.uFlash.value = flash
      sunDir.set(0.26, 0.02 + dawn * 0.22, -0.96).normalize()
      skyUniforms.uSunDir.value.copy(sunDir)

      group.position.set(camera.position.x, 0, camera.position.z)
      sunGlow.position.copy(sunDir).multiplyScalar(1450)
      sunGlow.material.opacity = 0.55 + dawn * 0.35 + flash * 0.5

      // Birds wheel around the player's neighbourhood.
      for (const bird of birds) {
        const d = bird.userData
        d.angle += d.speed * 0.016
        const x = focus.x + Math.cos(d.angle) * d.radius
        const z = focus.z + Math.sin(d.angle) * d.radius - 40
        const y = d.height + Math.sin(time * 0.5 + d.phase) * 3
        bird.position.set(x - group.position.x, y, z - group.position.z)
        bird.rotation.y = -d.angle + Math.PI / 2
        bird.rotation.z = Math.sin(time * 0.9 + d.phase) * 0.08
        const flap = Math.sin(time * 5.2 + d.phase) * 0.55
        const a = bird.geometry.attributes.position
        const s = d.size
        a.array[0] = -s * 1.5
        a.array[1] = flap * s + 0.12 * s
        a.array[2] = 0
        a.array[3] = 0
        a.array[4] = 0
        a.array[5] = 0
        a.array[6] = s * 1.5
        a.array[7] = flap * s + 0.12 * s
        a.array[8] = 0
        a.needsUpdate = true
        tmp.copy(bird.position)
      }
    },
  }
}

import * as THREE from 'three'
import { waterHeight, waterGradient } from './waves.js'

const TAU = Math.PI * 2
const UP = new THREE.Vector3(0, 1, 0)

function capsuleBetween(a, b, radius, material) {
  const dir = new THREE.Vector3().subVectors(b, a)
  const len = dir.length()
  const geo = new THREE.CapsuleGeometry(radius, Math.max(0.01, len - radius * 2), 4, 10)
  const mesh = new THREE.Mesh(geo, material)
  mesh.position.copy(a).addScaledVector(dir, 0.5)
  mesh.quaternion.setFromUnitVectors(UP, dir.normalize())
  return mesh
}

function buildRider() {
  const rider = new THREE.Group()
  const suit = new THREE.MeshStandardMaterial({ color: 0x141c2a, roughness: 0.62, metalness: 0.08 })
  const accent = new THREE.MeshStandardMaterial({ color: 0xff7a4d, roughness: 0.45, metalness: 0.1 })
  const skin = new THREE.MeshStandardMaterial({ color: 0xc98f6b, roughness: 0.75 })
  const hair = new THREE.MeshStandardMaterial({ color: 0x241716, roughness: 0.9 })

  const hip = new THREE.Vector3(0, 0.66, 0.18)
  const chest = new THREE.Vector3(0, 1.16, -0.02)
  const neck = new THREE.Vector3(0, 1.28, -0.08)

  // Torso leaning into the ride.
  rider.add(capsuleBetween(hip, chest, 0.17, suit))
  // Accent band across the chest.
  const band = capsuleBetween(new THREE.Vector3(-0.17, 1.03, -0.03), new THREE.Vector3(0.17, 1.03, -0.03), 0.055, accent)
  rider.add(band)
  const hips = new THREE.Mesh(new THREE.SphereGeometry(0.19, 12, 10), suit)
  hips.position.copy(hip)
  hips.scale.set(1.2, 0.8, 0.9)
  rider.add(hips)

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.155, 16, 12), skin)
  head.position.set(0, 1.44, -0.12)
  rider.add(head)
  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.162, 16, 12, 0, TAU, 0, Math.PI * 0.58), hair)
  cap.position.copy(head.position)
  cap.rotation.x = -0.25
  rider.add(cap)

  const shoulderL = new THREE.Vector3(-0.19, 1.15, -0.02)
  const shoulderR = new THREE.Vector3(0.19, 1.15, -0.02)
  const handL = new THREE.Vector3(-0.52, 0.86, 0.16)
  const handR = new THREE.Vector3(0.52, 0.9, 0.1)
  rider.add(capsuleBetween(shoulderL, handL, 0.065, suit))
  rider.add(capsuleBetween(shoulderR, handR, 0.065, suit))
  for (const p of [handL, handR]) {
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.065, 8, 8), skin)
    hand.position.copy(p)
    rider.add(hand)
  }

  const kneeL = new THREE.Vector3(-0.28, 0.56, -0.16)
  const kneeR = new THREE.Vector3(0.28, 0.56, -0.16)
  const footL = new THREE.Vector3(-0.24, 0.06, 0.2)
  const footR = new THREE.Vector3(0.24, 0.06, 0.24)
  rider.add(capsuleBetween(new THREE.Vector3(-0.15, 0.65, 0.15), kneeL, 0.09, suit))
  rider.add(capsuleBetween(new THREE.Vector3(0.15, 0.65, 0.15), kneeR, 0.09, suit))
  rider.add(capsuleBetween(kneeL, footL, 0.08, suit))
  rider.add(capsuleBetween(kneeR, footR, 0.08, suit))
  const boardShorts = new THREE.Mesh(new THREE.SphereGeometry(0.2, 12, 10), accent)
  boardShorts.position.set(0, 0.7, 0.14)
  boardShorts.scale.set(1.25, 0.72, 1.0)
  rider.add(boardShorts)

  rider.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = false
      o.receiveShadow = false
    }
  })
  return rider
}

function buildBoard() {
  const group = new THREE.Group()
  const boardMat = new THREE.MeshStandardMaterial({ color: 0xff7248, roughness: 0.3, metalness: 0.12 })
  const deckMat = new THREE.MeshStandardMaterial({ color: 0xffe3bd, roughness: 0.5, metalness: 0.02 })
  const railMat = new THREE.MeshStandardMaterial({ color: 0xffb27a, emissive: 0x43180b, emissiveIntensity: 0.8, roughness: 0.35 })

  const boardGeo = new THREE.CapsuleGeometry(0.43, 2.05, 6, 20)
  boardGeo.rotateX(Math.PI / 2)
  boardGeo.scale(1.0, 0.24, 1.12)
  const board = new THREE.Mesh(boardGeo, boardMat)
  board.position.y = 0.1
  group.add(board)

  const deckGeo = new THREE.CapsuleGeometry(0.3, 1.7, 4, 18)
  deckGeo.rotateX(Math.PI / 2)
  deckGeo.scale(1.0, 0.09, 1.15)
  const deck = new THREE.Mesh(deckGeo, deckMat)
  deck.position.y = 0.205
  group.add(deck)

  const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.02, 2.2), railMat)
  stripe.position.set(0, 0.245, 0)
  group.add(stripe)
  const tail = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.02, 0.08), railMat)
  tail.position.set(0, 0.245, 0.72)
  group.add(tail)

  // Skeg
  const finShape = new THREE.Shape()
  finShape.moveTo(0, 0)
  finShape.lineTo(0.14, 0)
  finShape.lineTo(-0.02, 0.38)
  finShape.closePath()
  const finGeo = new THREE.ExtrudeGeometry(finShape, { depth: 0.025, bevelEnabled: false })
  const fin = new THREE.Mesh(finGeo, railMat)
  fin.position.set(0.0, -0.02, 1.1)
  fin.rotation.y = Math.PI / 2
  group.add(fin)

  return group
}

export class Player {
  constructor(scene) {
    this.root = new THREE.Group()
    this.board = buildBoard()
    this.rider = buildRider()
    this.rider.position.set(0, 0.22, 0.18)
    this.root.add(this.board, this.rider)
    scene.add(this.root)

    this.pos = new THREE.Vector3(0, 0, 12)
    this.heading = 0
    this.speed = 17
    this.vy = 0
    this.airborne = false
    this.airTime = 0
    this.spin = 0
    this.flow = 0.35
    this.turnVis = 0
    this.pitchVis = 0
    this.rollVis = 0
    this.jumpCooldown = 0
    this.popCooldown = 0
    this.prevSlopeAhead = 0
    this.landed = null
    this.jumped = false
    this.carve = 0
    this.wasAir = false
    this.events = []
    this.grad = { x: 0, z: 0 }
    this.normal = new THREE.Vector3(0, 1, 0)
    this.reset()
  }

  reset() {
    this.pos.set(0, 0, 12)
    this.pos.y = waterHeight(this.pos.x, this.pos.z, 0) + 0.18
    this.heading = 0
    this.speed = 17
    this.vy = 0
    this.airborne = false
    this.airTime = 0
    this.spin = 0
    this.flow = 0.35
    this.turnVis = 0
    this.pitchVis = 0
    this.rollVis = 0
    this.jumpCooldown = 0
    this.popCooldown = 0
    this.prevSlopeAhead = 0
    this.landed = null
    this.jumped = false
    this.carve = 0
    this.events.length = 0
    this.root.rotation.set(0, 0, 0)
    this.root.position.copy(this.pos)
  }

  get forward() {
    return { x: Math.sin(this.heading), z: -Math.cos(this.heading) }
  }

  get right() {
    return { x: Math.cos(this.heading), z: Math.sin(this.heading) }
  }

  update(dt, time, input) {
    this.events.length = 0
    this.jumpCooldown = Math.max(0, this.jumpCooldown - dt)
    this.popCooldown = Math.max(0, this.popCooldown - dt)

    const surfY = waterHeight(this.pos.x, this.pos.z, time)
    waterGradient(this.pos.x, this.pos.z, time, this.grad)
    const fx = Math.sin(this.heading)
    const fz = -Math.cos(this.heading)
    const rx = Math.cos(this.heading)
    const rz = Math.sin(this.heading)
    const turn = input.turn || 0

    this.turnVis += (turn - this.turnVis) * Math.min(1, dt * 7)

    if (!this.airborne) {
      const slope = this.grad.x * fx + this.grad.z * fz

      // Downhill pull and drag: the swell does most of the work.
      this.speed += -slope * 78 * dt
      this.speed += (18.5 - this.speed) * 0.34 * dt
      this.speed += this.flow * 3.2 * dt
      this.speed -= Math.abs(turn) * this.speed * 0.11 * dt
      this.speed = THREE.MathUtils.clamp(this.speed, 8.5, 34)

      this.heading += turn * (1.05 + this.speed * 0.03) * dt

      this.pos.x += Math.sin(this.heading) * this.speed * dt
      this.pos.z += -Math.cos(this.heading) * this.speed * dt
      this.pos.y = surfY + 0.18

      // Flow builds by carving clean arcs across the face.
      if (Math.abs(turn) > 0.22 && this.speed > 11) {
        this.flow += dt * 0.25
        this.carve = Math.min(1, this.carve + dt * 2.2)
      } else {
        this.flow -= dt * 0.11
        this.carve = Math.max(0, this.carve - dt * 1.4)
      }
      this.flow = THREE.MathUtils.clamp(this.flow, 0, 1)

      // Crest launch: if we just crested a steep face, the lip throws us.
      const ahead = 2.4
      const slopeAhead = (waterHeight(this.pos.x + fx * ahead, this.pos.z + fz * ahead, time) - surfY) / ahead
      if (
        this.popCooldown <= 0 &&
        this.speed > 16.5 &&
        this.prevSlopeAhead > 0.065 &&
        slopeAhead < 0.035
      ) {
        this.launch(7.2 + Math.min(8.0, this.speed * 0.22), true)
      }
      this.prevSlopeAhead = slopeAhead

      if (input.jumpPressed && this.jumpCooldown <= 0) {
        this.launch(9.0 + Math.max(0, -slope) * 9, false)
      }
    } else {
      // Airborne: keep momentum, spin the board, gravity brings us home.
      this.pos.x += Math.sin(this.heading) * this.speed * dt
      this.pos.z += -Math.cos(this.heading) * this.speed * dt
      this.pos.y += this.vy * dt
      this.vy -= 24 * dt
      this.speed -= 0.7 * dt
      this.spin += turn * 4.4 * dt
      this.heading += turn * 0.45 * dt
      this.airTime += dt

      if (this.pos.y <= surfY + 0.16 && this.vy < 0) {
        this.land(surfY)
      }
    }

    this.root.position.copy(this.pos)
    this.updateVisual(dt, time, turn, surfY)
  }

  launch(vy, auto) {
    this.airborne = true
    this.airTime = 0
    this.vy = vy
    this.spin = 0
    this.jumpCooldown = 0.55
    this.popCooldown = auto ? 2.4 : 0.35
    this.flow = Math.max(0, this.flow - 0.12)
    this.jumped = true
    this.events.push({ type: 'jump', auto, strength: vy })
  }

  land(surfY) {
    const deg = Math.abs(this.spin)
    const rotations = Math.floor((deg + 0.6) / TAU)
    const rem = Math.abs(deg - Math.round(deg / TAU) * TAU)
    const clean = rem < 0.9
    const impact = Math.abs(this.vy)
    const air = this.airTime

    this.airborne = false
    this.vy = 0
    this.spin = 0
    this.pos.y = surfY + 0.18
    this.airTime = 0
    this.wasAir = true

    if (clean) {
      this.speed += 2.2 + Math.min(4, rotations * 0.9)
      this.flow = Math.min(1, this.flow + 0.22)
    } else {
      this.speed *= 0.52
      this.flow = 0
    }
    this.events.push({ type: 'land', clean, rotations, air, impact })
  }

  updateVisual(dt, time, turn, surfY) {
    const fx = Math.sin(this.heading)
    const fz = -Math.cos(this.heading)
    const rx = Math.cos(this.heading)
    const rz = Math.sin(this.heading)

    let pitch
    let roll
    if (this.airborne) {
      pitch = THREE.MathUtils.clamp(this.vy * 0.035, -0.45, 0.5) - 0.05
      roll = turn * 0.42
      this.pitchVis += (pitch - this.pitchVis) * Math.min(1, dt * 6)
      this.rollVis += (roll - this.rollVis) * Math.min(1, dt * 6)
      this.root.rotation.set(this.pitchVis, this.heading + this.spin, this.rollVis, 'YXZ')
    } else {
      const hF = waterHeight(this.pos.x + fx * 1.5, this.pos.z + fz * 1.5, time)
      const hB = waterHeight(this.pos.x - fx * 1.5, this.pos.z - fz * 1.5, time)
      const hR = waterHeight(this.pos.x + rx * 0.9, this.pos.z + rz * 0.9, time)
      const hL = waterHeight(this.pos.x - rx * 0.9, this.pos.z - rz * 0.9, time)
      pitch = Math.atan2(hF - hB, 3.0)
      roll = Math.atan2(hR - hL, 1.8) - turn * 0.30
      this.pitchVis += (pitch - this.pitchVis) * Math.min(1, dt * 9)
      this.rollVis += (roll - this.rollVis) * Math.min(1, dt * 8)
      this.root.rotation.set(this.pitchVis, this.heading, this.rollVis, 'YXZ')
    }

    const crouch = this.airborne ? 0.55 : 0.16 + (this.speed / 34) * 0.24 + this.carve * 0.1
    this.rider.position.y = 0.22 - crouch * 0.24
    this.rider.rotation.x = -0.12 - crouch * 0.34
    this.rider.rotation.z = -this.turnVis * 0.24
    this.rider.rotation.y = this.turnVis * 0.12
  }

  samplePoint(x, z, time) {
    waterHeight(x, z, time)
  }
}

import * as THREE from 'three'
import { waterHeight } from './waves.js'

export function makeGlowTexture(inner = 'rgba(255,244,214,1)', mid = 'rgba(255,190,110,0.55)') {
  const c = document.createElement('canvas')
  c.width = c.height = 128
  const g = c.getContext('2d')
  const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64)
  grad.addColorStop(0, inner)
  grad.addColorStop(0.25, mid)
  grad.addColorStop(1, 'rgba(255,120,40,0)')
  g.fillStyle = grad
  g.fillRect(0, 0, 128, 128)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

const sprayVert = /* glsl */ `
attribute float aSize;
attribute float aAlpha;
attribute vec3 aColor;
varying float vAlpha;
varying vec3 vColor;
void main() {
  vAlpha = aAlpha;
  vColor = aColor;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = aSize * (260.0 / max(1.0, -mv.z));
  gl_Position = projectionMatrix * mv;
}
`

const sprayFrag = /* glsl */ `
varying float vAlpha;
varying vec3 vColor;
void main() {
  float d = length(gl_PointCoord - vec2(0.5));
  if (d > 0.5) discard;
  float a = smoothstep(0.5, 0.06, d);
  gl_FragColor = vec4(vColor, a * vAlpha);
}
`

export class Spray {
  constructor(scene, max = 1100) {
    this.max = max
    this.count = 0
    this.pos = new Float32Array(max * 3)
    this.col = new Float32Array(max * 3)
    this.size = new Float32Array(max)
    this.alpha = new Float32Array(max)
    this.vel = new Float32Array(max * 3)
    this.life = new Float32Array(max)
    this.maxLife = new Float32Array(max)
    this.baseSize = new Float32Array(max)
    this.cursor = 0

    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3))
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3))
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1))
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1))
    geo.setDrawRange(0, max)
    const mat = new THREE.ShaderMaterial({
      vertexShader: sprayVert,
      fragmentShader: sprayFrag,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    })
    this.points = new THREE.Points(geo, mat)
    this.points.frustumCulled = false
    scene.add(this.points)
    this.geo = geo
  }

  spawn(x, y, z, vx, vy, vz, size, life, tint = 1) {
    const i = this.cursor
    this.cursor = (this.cursor + 1) % this.max
    const i3 = i * 3
    this.pos[i3] = x
    this.pos[i3 + 1] = y
    this.pos[i3 + 2] = z
    this.vel[i3] = vx
    this.vel[i3 + 1] = vy
    this.vel[i3 + 2] = vz
    this.life[i] = life
    this.maxLife[i] = life
    this.baseSize[i] = size
    this.size[i] = size
    this.alpha[i] = 0.95
    this.col[i3] = 1.0 * tint
    this.col[i3 + 1] = (0.94 + 0.05 * tint) * tint
    this.col[i3 + 2] = 0.86 * tint
  }

  carving(player, intensity = 1) {
    const { x, z } = player.pos
    const fx = Math.sin(player.heading)
    const fz = -Math.cos(player.heading)
    const rx = Math.cos(player.heading)
    const rz = Math.sin(player.heading)
    const side = Math.sign(player.turnVis) || 1
    const n = Math.round(2 + intensity * 5)
    for (let i = 0; i < n; i++) {
      const back = 0.4 + Math.random() * 1.6
      const spread = (Math.random() - 0.5) * 1.2
      this.spawn(
        x - fx * back + rx * (side * 0.5 + spread),
        waterHeight(x, z, player.time || 0) + 0.25 + Math.random() * 0.35,
        z - fz * back + rz * (side * 0.5 + spread),
        rx * side * (2 + Math.random() * 5) - fx * (2 + Math.random() * 3),
        2.2 + Math.random() * 4.6,
        rz * side * (2 + Math.random() * 5) - fz * (2 + Math.random() * 3),
        0.16 + Math.random() * 0.34,
        0.5 + Math.random() * 0.55,
      )
    }
  }

  burst(x, y, z, count, power, up = 5) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2
      const r = Math.random() * power
      this.spawn(
        x + Math.cos(a) * r * 0.2,
        y + Math.random() * 0.5,
        z + Math.sin(a) * r * 0.2,
        Math.cos(a) * r,
        up * (0.35 + Math.random()),
        Math.sin(a) * r,
        0.2 + Math.random() * 0.5,
        0.6 + Math.random() * 0.9,
      )
    }
  }

  update(dt) {
    for (let i = 0; i < this.max; i++) {
      if (this.life[i] <= 0) {
        this.alpha[i] = 0
        this.size[i] = 0
        continue
      }
      this.life[i] -= dt
      const t = Math.max(0, this.life[i] / this.maxLife[i])
      const i3 = i * 3
      this.vel[i3 + 1] -= 15 * dt
      this.vel[i3] *= 1 - dt * 0.9
      this.vel[i3 + 2] *= 1 - dt * 0.9
      this.pos[i3] += this.vel[i3] * dt
      this.pos[i3 + 1] += this.vel[i3 + 1] * dt
      this.pos[i3 + 2] += this.vel[i3 + 2] * dt
      this.alpha[i] = Math.min(1, t * 1.7) * 0.9
      this.size[i] = this.baseSize[i] * (0.45 + (1 - t) * 1.5)
    }
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.aColor.needsUpdate = true
    this.geo.attributes.aSize.needsUpdate = true
    this.geo.attributes.aAlpha.needsUpdate = true
  }
}

const wakeVert = /* glsl */ `
attribute float aAlpha;
varying float vA;
void main() {
  vA = aAlpha;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`
const wakeFrag = /* glsl */ `
varying float vA;
void main() {
  if (vA <= 0.002) discard;
  gl_FragColor = vec4(vec3(1.0, 0.95, 0.88), vA);
}
`

export class Wake {
  constructor(scene, max = 100) {
    this.max = max
    this.samples = []
    this.timer = 0
    this.positions = new Float32Array(max * 2 * 3)
    this.alphas = new Float32Array(max * 2)
    this.geo = new THREE.BufferGeometry()
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    this.geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1))
    const index = []
    for (let i = 0; i < max - 1; i++) {
      const a = i * 2
      index.push(a, a + 1, a + 2, a + 1, a + 3, a + 2)
    }
    this.geo.setIndex(index)
    this.geo.setDrawRange(0, 0)
    const mat = new THREE.ShaderMaterial({
      vertexShader: wakeVert,
      fragmentShader: wakeFrag,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
    })
    this.mesh = new THREE.Mesh(this.geo, mat)
    this.mesh.frustumCulled = false
    this.mesh.renderOrder = 1
    scene.add(this.mesh)
  }

  clear() {
    this.samples.length = 0
    this.geo.setDrawRange(0, 0)
  }

  update(dt, player, time) {
    this.timer += dt
    if (!player.airborne && player.speed > 3 && this.timer > 0.035) {
      this.timer = 0
      this.samples.push({
        x: player.pos.x,
        z: player.pos.z,
        rx: Math.cos(player.heading),
        rz: Math.sin(player.heading),
        age: 0,
        speed: player.speed,
      })
      if (this.samples.length > this.max) this.samples.shift()
    }
    for (const s of this.samples) s.age += dt

    const n = this.samples.length
    for (let i = 0; i < n; i++) {
      const s = this.samples[i]
      const width = 0.42 + s.age * 1.5 + (i / Math.max(1, n)) * 0.4
      const y = waterHeight(s.x, s.z, time) + 0.09
      const a = i * 6
      this.positions[a] = s.x - s.rx * width
      this.positions[a + 1] = y
      this.positions[a + 2] = s.z - s.rz * width
      this.positions[a + 3] = s.x + s.rx * width
      this.positions[a + 4] = y
      this.positions[a + 5] = s.z + s.rz * width
      const fade = Math.max(0, 1 - s.age / 2.8) * (0.24 + Math.min(0.34, s.speed / 110))
      const b = i * 2
      this.alphas[b] = fade
      this.alphas[b + 1] = fade
    }
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.aAlpha.needsUpdate = true
    this.geo.setDrawRange(0, Math.max(0, (n - 1) * 6))
  }
}

export class Orbs {
  constructor(scene, count = 8) {
    this.scene = scene
    this.list = []
    this.glowTex = makeGlowTexture()
    const gemGeo = new THREE.IcosahedronGeometry(0.46, 1)
    for (let i = 0; i < count; i++) {
      const group = new THREE.Group()
      const gem = new THREE.Mesh(
        gemGeo,
        new THREE.MeshBasicMaterial({ color: 0xffe2a6, toneMapped: false }),
      )
      const core = new THREE.Mesh(
        new THREE.IcosahedronGeometry(0.72, 1),
        new THREE.MeshBasicMaterial({ color: 0xffb45e, transparent: true, opacity: 0.24, blending: THREE.AdditiveBlending, depthWrite: false }),
      )
      const glow = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: this.glowTex,
          color: 0xffc070,
          transparent: true,
          opacity: 0.85,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }),
      )
      glow.scale.setScalar(9)
      group.add(gem, core, glow)
      group.userData.phase = Math.random() * Math.PI * 2
      this.list.push({ group, gem, active: false, spin: Math.random() * 6 })
      scene.add(group)
    }
  }

  spawn(orb, player) {
    const h = player.heading
    const dist = 42 + Math.random() * 85
    const lateral = (Math.random() - 0.5) * 78
    const fx = Math.sin(h)
    const fz = -Math.cos(h)
    const rx = Math.cos(h)
    const rz = Math.sin(h)
    const x = player.pos.x + fx * dist + rx * lateral
    const z = player.pos.z + fz * dist + rz * lateral
    orb.group.position.set(x, 0, z)
    orb.active = true
    orb.group.visible = true
  }

  reset(player) {
    for (const orb of this.list) {
      this.spawn(orb, player)
    }
  }

  update(dt, time, player) {
    const collected = []
    for (const orb of this.list) {
      if (!orb.active) continue
      const dx = orb.group.position.x - player.pos.x
      const dz = orb.group.position.z - player.pos.z
      const flat = Math.hypot(dx, dz)
      if (flat > 170 || dz * -Math.cos(player.heading) + dx * Math.sin(player.heading) < -30) {
        this.spawn(orb, player)
        continue
      }
      const y = waterHeight(orb.group.position.x, orb.group.position.z, time) + 2.0 + Math.sin(time * 1.6 + orb.group.userData.phase) * 0.35
      orb.group.position.y = y
      orb.gem.rotation.y += dt * 1.4
      orb.gem.rotation.x += dt * 0.7
      const pulse = 1 + Math.sin(time * 2 + orb.group.userData.phase) * 0.08
      orb.group.scale.setScalar(pulse)
      if (flat < 3.4 && Math.abs(player.pos.y - y) < 4.2) {
        collected.push(orb.group.position.clone())
        orb.active = false
        orb.group.visible = false
        this.spawn(orb, player)
      }
    }
    return collected
  }
}

// Tiny procedural soundscape — no external assets, unlocked from the start gesture.
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.oceanGain = null
    this.oceanFilter = null
    this.windGain = null
    this.windFilter = null
    this.muted = false
    this.noise = null
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {})
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    try {
      const ctx = new AC()
      this.ctx = ctx
      this.master = ctx.createGain()
      this.master.gain.value = this.muted ? 0 : 0.85
      this.master.connect(ctx.destination)

      const len = Math.floor(ctx.sampleRate * 4)
      const buffer = ctx.createBuffer(1, len, ctx.sampleRate)
      const data = buffer.getChannelData(0)
      let last = 0
      for (let i = 0; i < len; i++) {
        const white = Math.random() * 2 - 1
        last = (last + 0.018 * white) / 1.018
        data[i] = last * 3.4
      }
      this.noise = buffer

      // Deep rolling ocean.
      const src = ctx.createBufferSource()
      src.buffer = buffer
      src.loop = true
      const filter = ctx.createBiquadFilter()
      filter.type = 'lowpass'
      filter.frequency.value = 420
      filter.Q.value = 0.7
      const gain = ctx.createGain()
      gain.gain.value = 0.0001
      src.connect(filter)
      filter.connect(gain)
      gain.connect(this.master)
      src.start()
      this.oceanGain = gain
      this.oceanFilter = filter
      gain.gain.setTargetAtTime(0.24, ctx.currentTime, 2.0)

      // Wind / spray hiss.
      const src2 = ctx.createBufferSource()
      src2.buffer = buffer
      src2.loop = true
      const bp = ctx.createBiquadFilter()
      bp.type = 'bandpass'
      bp.frequency.value = 1150
      bp.Q.value = 0.45
      const wg = ctx.createGain()
      wg.gain.value = 0.0001
      src2.connect(bp)
      bp.connect(wg)
      wg.connect(this.master)
      src2.start()
      this.windGain = wg
      this.windFilter = bp
      wg.gain.setTargetAtTime(0.035, ctx.currentTime, 2.5)
    } catch {
      this.ctx = null
    }
  }

  setMotion(speed, flow) {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const s = Math.min(1, Math.max(0, (speed - 10) / 24))
    this.oceanGain.gain.setTargetAtTime(0.18 + s * 0.2 + flow * 0.05, t, 0.25)
    this.oceanFilter.frequency.setTargetAtTime(330 + s * 480, t, 0.3)
    this.windGain.gain.setTargetAtTime(0.02 + s * 0.075, t, 0.4)
    this.windFilter.frequency.setTargetAtTime(850 + s * 900, t, 0.4)
  }

  setMuted(muted) {
    this.muted = muted
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(muted ? 0 : 0.85, this.ctx.currentTime, 0.12)
  }

  chime(step = 0) {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime
    const base = 660 * Math.pow(2, (step % 5) / 12)
    for (const [mult, vol] of [[1, 0.09], [1.5, 0.04], [2, 0.02]]) {
      const osc = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      osc.type = 'sine'
      osc.frequency.setValueAtTime(base * mult, t)
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(vol, t + 0.012)
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.75)
      osc.connect(g)
      g.connect(this.master)
      osc.start(t)
      osc.stop(t + 0.8)
    }
  }

  whoosh(power = 1) {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    const bp = this.ctx.createBiquadFilter()
    bp.type = 'bandpass'
    bp.Q.value = 0.8
    bp.frequency.setValueAtTime(360, t)
    bp.frequency.exponentialRampToValueAtTime(1500, t + 0.32)
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.11 * power, t + 0.05)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.45)
    src.connect(bp)
    bp.connect(g)
    g.connect(this.master)
    src.start(t)
    src.stop(t + 0.5)
  }

  splash(power = 1) {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    const lp = this.ctx.createBiquadFilter()
    lp.type = 'lowpass'
    lp.frequency.setValueAtTime(1800, t)
    lp.frequency.exponentialRampToValueAtTime(260, t + 0.5)
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.16 * power, t + 0.02)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.55)
    src.connect(lp)
    lp.connect(g)
    g.connect(this.master)
    src.start(t)
    src.stop(t + 0.6)

    const osc = this.ctx.createOscillator()
    const og = this.ctx.createGain()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(105, t)
    osc.frequency.exponentialRampToValueAtTime(44, t + 0.25)
    og.gain.setValueAtTime(0.0001, t)
    og.gain.exponentialRampToValueAtTime(0.1 * power, t + 0.01)
    og.gain.exponentialRampToValueAtTime(0.0001, t + 0.35)
    osc.connect(og)
    og.connect(this.master)
    osc.start(t)
    osc.stop(t + 0.4)
  }

  dawnChord() {
    if (!this.ctx || this.muted) return
    const notes = [392, 494, 587, 784]
    notes.forEach((f, i) => {
      const t = this.ctx.currentTime + i * 0.16
      const osc = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      osc.type = i === 3 ? 'triangle' : 'sine'
      osc.frequency.value = f
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(0.06, t + 0.06)
      g.gain.exponentialRampToValueAtTime(0.0001, t + 2.2)
      osc.connect(g)
      g.connect(this.master)
      osc.start(t)
      osc.stop(t + 2.3)
    })
  }
}

import * as THREE from 'three'
