const lookTarget = new THREE.Vector3(0, 4, -60)
const camGoal = new THREE.Vector3()
const desiredLook = new THREE.Vector3()
const tmpV = new THREE.Vector3()

function updateCamera(dt, time) {
  if (game.state === 'title') {
    const drift = time * 0.16
    camGoal.set(
      player.pos.x - 3.4 + Math.sin(drift) * 2.2,
      player.pos.y + 5.3 + Math.sin(time * 0.31) * 0.28,
      player.pos.z + 13.4 + Math.cos(drift) * 1.6,
    )
    const wh = waterHeight(camGoal.x, camGoal.z, time)
    camGoal.y = Math.max(camGoal.y, wh + 1.6)
    camera.position.lerp(camGoal, 1 - Math.exp(-dt * 5))
    desiredLook.set(player.pos.x - 9.5, player.pos.y + 3.05, player.pos.z - 92)
    lookTarget.lerp(desiredLook, 1 - Math.exp(-dt * 4))
    camera.lookAt(lookTarget)
    camera.fov += (64 - camera.fov) * Math.min(1, dt * 3)
    camera.updateProjectionMatrix()
    camera.up.set(0, 1, 0)
    return
  }

  const finale = game.state === 'finale'
  const k = finale ? THREE.MathUtils.smoothstep(game.finaleT, 0, 3.2) : 0
  const fx = Math.sin(player.heading)
  const fz = -Math.cos(player.heading)
  const back = 8.7 + player.speed * 0.095 + k * 9
  const height = 4.35 + player.speed * 0.032 + (player.airborne ? 1.25 : 0) + k * 6.2

  camGoal.set(
    player.pos.x - fx * back,
    player.pos.y + height,
    player.pos.z - fz * back,
  )
  const wh = waterHeight(camGoal.x, camGoal.z, time)
  camGoal.y = Math.max(camGoal.y, wh + 1.75)
  const rate = finale ? 2.2 : player.airborne ? 3.2 : 5.2
  camera.position.lerp(camGoal, 1 - Math.exp(-dt * rate))

  const ahead = 9 + player.speed * 0.28 + k * 15
  desiredLook.set(
    player.pos.x + fx * ahead,
    player.pos.y + 2.0 + k * 7.5,
    player.pos.z + fz * ahead,
  )
  lookTarget.lerp(desiredLook, 1 - Math.exp(-dt * (finale ? 1.8 : 6.5)))
  camera.up.set(-Math.sin(player.turnVis) * 0.075, 1, 0).normalize()
  camera.lookAt(lookTarget)

  const targetFov = 67 + Math.min(14, (player.speed - 12) * 0.62) + k * 8
  camera.fov += (targetFov - camera.fov) * Math.min(1, dt * 3.4)
  camera.updateProjectionMatrix()

  if (game.shake > 0.001) {
    camera.position.x += (Math.random() - 0.5) * game.shake * 0.8
    camera.position.y += (Math.random() - 0.5) * game.shake * 0.55
    camera.position.z += (Math.random() - 0.5) * game.shake * 0.8
  }
}

// ------- update -------
const clock = new THREE.Clock()
let hudClock = 0
let audioClock = 0
let sprayClock = 0
let lastOrbToast = -10

function handlePlayerEvents() {
  for (const ev of player.events) {
    if (ev.type === 'jump') {
      audio.whoosh(clamp(ev.strength / 14, 0.4, 1.4))
      spray.burst(player.pos.x, player.pos.y + 0.1, player.pos.z, 14, 3.4, 3.0)
